            return cmd_watch(config)
        if args.command == "status":
            return cmd_status(config)
    except (DiscoveryError, PublishError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
